package finder

// Recognizing registrars: the comment that marks a generated file, the registration function
// signatures the RPC code generators emit, and the generated fx registrars that wrap them.

import (
	"go/ast"
	"go/types"
	"regexp"
	"strings"

	fty "github.com/uber-research/rpcshield/go/finder/types"
)

// _generatedMarker matches the comment lines that mark a generated file: the Go convention
// ("// Code generated ... DO NOT EDIT."), the same line without its ending, which some
// generators split over several lines, and the "@generated" line the thriftrw and YARPC
// generators emit.
var _generatedMarker = regexp.MustCompile(`^// Code generated |^// @generated`)

// isGeneratedFile reports whether a marker comment precedes the file's package clause.
//
// Accepted (any one line suffices):
//
//	// Code generated by protoc-gen-go-grpc. DO NOT EDIT.       Go convention
//	// Code generated by thriftrw v1.29.2. DO NOT EDIT.
//	// Code generated by                                        marker split over two lines
//	//     thriftrw-plugin-yarpc. DO NOT EDIT.
//	// @generated                                               thriftrw, YARPC
//
// Rejected:
//
//	// This file is not code generated by hand.                 marker not at the line start
//	package foo
//	// Code generated by x. DO NOT EDIT.                        after the package clause
//
// The file's comment groups are in position order, so the scan stops at the first group past
// the package keyword; only header comments are considered.
func isGeneratedFile(file *ast.File) bool {
	for _, group := range file.Comments {
		if group.Pos() > file.Package {
			break
		}
		for _, c := range group.List {
			if _generatedMarker.MatchString(c.Text) {
				return true
			}
		}
	}
	return false
}

// stripVendor removes a vendor directory prefix from a package path.
//
//	example.com/app/vendor/google.golang.org/grpc -> google.golang.org/grpc
//	vendor/google.golang.org/grpc                 -> google.golang.org/grpc
//	google.golang.org/grpc                        -> unchanged
func stripVendor(path string) string {
	if i := strings.LastIndex(path, "/vendor/"); i >= 0 {
		return path[i+len("/vendor/"):]
	}
	return strings.TrimPrefix(path, "vendor/")
}

// isNamedType reports whether t is the named type pkgPath.name, ignoring vendoring and aliases.
//
//	isNamedType(grpc.ServiceRegistrar, "google.golang.org/grpc", "ServiceRegistrar") -> true
//	isNamedType(*grpc.Server, "google.golang.org/grpc", "Server")                   -> false (pointer; callers unwrap it)
//	isNamedType(mygrpc.Server, ...) where mygrpc is a vendored copy                 -> true
//	isNamedType(S, ...) where "type S = grpc.ServiceRegistrar"                      -> true
func isNamedType(t types.Type, pkgPath, name string) bool {
	n, ok := types.Unalias(t).(*types.Named)
	return ok && n.Obj().Pkg() != nil && n.Obj().Name() == name && stripVendor(n.Obj().Pkg().Path()) == pkgPath
}

const (
	_yarpcTransportPkg = "go.uber.org/yarpc/api/transport"
	_yarpcProtobufPkg  = "go.uber.org/yarpc/encoding/protobuf"
	_yarpcThriftPkg    = "go.uber.org/yarpc/encoding/thrift"
	_tchannelThriftPkg = "github.com/uber/tchannel-go/thrift"
	_grpcPkg           = "google.golang.org/grpc"
	_apacheThriftPkg   = "github.com/apache/thrift/lib/go/thrift"
)

// importsPackageTree reports whether imports has root or a package below it.
//
//	{"go.uber.org/yarpc/encoding/protobuf"}        root "go.uber.org/yarpc/encoding/protobuf" -> true
//	{"go.uber.org/yarpc/encoding/protobuf/v2"}     same root                                   -> true
//	{"go.uber.org/yarpc/encoding/protobufx"}       same root                                   -> false
func importsPackageTree(imports map[string]bool, root string) bool {
	for path := range imports {
		if path == root || strings.HasPrefix(path, root+"/") {
			return true
		}
	}
	return false
}

// registrarShapeOf matches fn against the registration function shapes the RPC code generators
// emit and returns the index of the parameter that receives the handler and the endpoint type.
// imports are the (vendor-stripped) import paths of fn's package; tProcessor is the Apache
// Thrift TProcessor interface, or nil when that package is not in the program.
//
// Accepted, with I the server interface:
//
//	YARPC protobuf   func BuildKVYARPCProcedures(server I, opts ...)  []transport.Procedure
//	                 package imports go.uber.org/yarpc/encoding/protobuf[/v2]   -> 0, TypeGRPC
//	YARPC thrift     func New(impl I, opts ...thrift.RegisterOption) []transport.Procedure
//	                 package imports go.uber.org/yarpc/encoding/thrift[/v2]     -> 0, TypeThrift
//	TChannel thrift  func NewTChanKVServer(handler I) thrift.TChanServer       -> 0, TypeThriftTChannel
//	gRPC             func RegisterKVServer(s grpc.ServiceRegistrar, srv I)     -> 1, TypeGRPC
//	                 func RegisterKVServer(s *grpc.Server, srv I)              -> 1, TypeGRPC (grpc-go before 1.32)
//	Apache Thrift    func NewKVProcessor(handler I) *KVProcessor
//	                 where *KVProcessor implements thrift.TProcessor           -> 0, TypeThrift
//
// Rejected: methods; a []transport.Procedure result in a package that imports neither YARPC
// encoding (hand-written procedure builders); func(I) P when tProcessor is nil; everything else.
//
// The first result type is examined first (YARPC, TChannel), then a two-parameter, no-result
// signature's first parameter (gRPC), then a one-in-one-out signature's result (Apache Thrift).
// The caller checks separately that fn is declared in a generated file and that parameter
// handlerParam is a named interface with at least one method.
func registrarShapeOf(fn *types.Func, imports map[string]bool, tProcessor *types.Interface) (handlerParam int, endpointType fty.EndpointType, ok bool) {
	sig, isSig := fn.Type().(*types.Signature)
	if !isSig || sig.Recv() != nil {
		return 0, "", false
	}
	params, results := sig.Params(), sig.Results()
	if results.Len() >= 1 && params.Len() >= 1 {
		if sl, isSlice := types.Unalias(results.At(0).Type()).(*types.Slice); isSlice && isNamedType(sl.Elem(), _yarpcTransportPkg, "Procedure") {
			switch {
			case importsPackageTree(imports, _yarpcProtobufPkg):
				return 0, fty.TypeGRPC, true
			case importsPackageTree(imports, _yarpcThriftPkg):
				return 0, fty.TypeThrift, true
			}
			return 0, "", false
		}
		if isNamedType(results.At(0).Type(), _tchannelThriftPkg, "TChanServer") {
			return 0, fty.TypeThriftTChannel, true
		}
	}
	if params.Len() == 2 && results.Len() == 0 {
		first := params.At(0).Type()
		if p, isPtr := types.Unalias(first).(*types.Pointer); isPtr {
			if isNamedType(p.Elem(), _grpcPkg, "Server") {
				return 1, fty.TypeGRPC, true
			}
		} else if isNamedType(first, _grpcPkg, "ServiceRegistrar") {
			return 1, fty.TypeGRPC, true
		}
	}
	if tProcessor != nil && params.Len() == 1 && results.Len() == 1 && types.Implements(results.At(0).Type(), tProcessor) {
		return 0, fty.TypeThrift, true
	}
	return 0, "", false
}

// isFxInType reports whether t is fx.In or dig.In, the marker fx parameter structs embed.
func isFxInType(t types.Type) bool {
	return isNamedType(t, "go.uber.org/fx", "In") || isNamedType(t, "go.uber.org/dig", "In")
}

// isFxFunc reports whether fn is the package-level function go.uber.org/fx.name.
func isFxFunc(fn *types.Func, name string) bool {
	return fn != nil && fn.Pkg() != nil && fn.Name() == name && stripVendor(fn.Pkg().Path()) == "go.uber.org/fx"
}

// collectFxRegistrar records fn as an fx registrar if its body contains a function literal with
// a parameter struct that has a field of a server-interface type. servers maps each server
// interface to its registrar. This is the shape protoc-gen-yarpc-go and thriftrw-plugin-yarpc
// generate so that fx can supply the handler:
//
//	// Code generated by protoc-gen-yarpc-go. DO NOT EDIT.
//	type FxKVYARPCProceduresParams struct {
//		fx.In
//		Server KVYARPCServer
//	}
//	func NewFxKVYARPCProcedures() interface{} {
//		return func(params FxKVYARPCProceduresParams) FxKVYARPCProceduresResult {
//			return FxKVYARPCProceduresResult{Procedures: BuildKVYARPCProcedures(params.Server)}
//		}
//	}
//	        -> fxRegistrars[NewFxKVYARPCProcedures] = [registrar of BuildKVYARPCProcedures]
//
// Hand-written code calls fx.Provide(kvpb.NewFxKVYARPCProcedures()), and fx passes whatever
// value was provided as KVYARPCServer, so the registration inside the literal is attributed to
// those calls (see registeredHandlers), not to the literal. A function whose literals take no
// struct with a server-interface field is not recorded; a struct with two server fields yields
// two registrars.
func (ix *registrationIndex) collectFxRegistrar(info *types.Info, fn *types.Func, fd *ast.FuncDecl, servers map[*types.TypeName]*registrar) {
	ast.Inspect(fd.Body, func(n ast.Node) bool {
		lit, ok := n.(*ast.FuncLit)
		if !ok {
			return true
		}
		sig, _ := info.TypeOf(lit).(*types.Signature)
		if sig == nil {
			return true
		}
		for i := 0; i < sig.Params().Len(); i++ {
			st, ok := sig.Params().At(i).Type().Underlying().(*types.Struct)
			if !ok {
				continue
			}
			for j := 0; j < st.NumFields(); j++ {
				if named, ok := types.Unalias(st.Field(j).Type()).(*types.Named); ok {
					if r := servers[named.Obj()]; r != nil {
						ix.fxRegistrars[fn] = append(ix.fxRegistrars[fn], r)
					}
				}
			}
		}
		return true
	})
}
